import {chromium} from 'playwright';
import {mkdir,writeFile} from 'node:fs/promises';
import assert from 'node:assert/strict';
const out=process.env.ORBIT_CAMERA_OUT||'/tmp/orbit-source-camera';await mkdir(out,{recursive:true});
const b=await chromium.launch({args:['--use-angle=swiftshader','--enable-unsafe-swiftshader']});const p=await b.newPage({viewport:{width:393,height:800},isMobile:true,hasTouch:true});await p.route(/https:\/\/(?:[^/]+\.)?(?:googlesyndication\.com|doubleclick\.net|googleadservices\.com)\//,r=>r.abort());const results=[];
async function loaded(){await p.getByTestId('anatomy-renderer').locator('canvas').waitFor();await p.waitForFunction(()=>!/LOADING (BODYPARTS3D|Z-ANATOMY|HRA)/.test(document.querySelector('[data-testid="anatomy-renderer"]').textContent),null,{timeout:180000});await p.waitForTimeout(1300);}
async function pixels(){return p.getByTestId('anatomy-renderer').locator('canvas').evaluate(c=>new Promise(resolve=>requestAnimationFrame(()=>{const gl=c.getContext('webgl2')||c.getContext('webgl'),w=gl.drawingBufferWidth,h=gl.drawingBufferHeight,px=new Uint8Array(w*h*4);gl.readPixels(0,0,w,h,gl.RGBA,gl.UNSIGNED_BYTE,px);let count=0;for(let i=0;i<px.length;i+=4)if(px[i]+px[i+1]+px[i+2]>100)count++;resolve({count,w,h});})));}
try{for(const [organ,overview,title,id] of [['kidney','hra_kidney_overview','Renal columns · HRA','hra_kidney_columns'],['heart','hra_heart_overview','Pulmonary valve · HRA','hra_pulmonary_valve']]){
 await p.goto('http://127.0.0.1:4180/simulator?mode=anatomy&organ='+organ+'&isolate='+overview+'&nativeTheme=dark');await loaded();const d=p.getByTestId('organ-detail-drawer');if(await d.isVisible())await d.getByRole('button',{name:'Close',exact:true}).click();await loaded();const before=await pixels();await p.getByTitle(title,{exact:true}).click();await p.getByTestId('anatomy-renderer').locator('canvas').scrollIntoViewIfNeeded();await loaded();const after=await pixels();await p.screenshot({path:out+'/'+id+'.png'});results.push({id,before,after});console.log(JSON.stringify(results.at(-1)));if(process.env.ORBIT_EXPECT_FIXED==='1')assert(after.count>100,'Selected source disappeared after its region preset changed');
 }}finally{await writeFile(out+'/results.json',JSON.stringify(results,null,2));await b.close();}
